import unittest
from datetime import datetime
from dateutil.rrule import rrule, rrulestr, DAILY

class CountZeroTest(unittest.TestCase):
    def testCountZero(self):
        self.assertEqual(list(rrule(DAILY, count=0)), [])
    def testCountZeroCount(self):
        self.assertEqual(rrule(DAILY, count=0).count(), 0)
    def testCountZeroStr(self):
        self.assertIn('COUNT=0', str(rrule(DAILY, count=0, dtstart=datetime(2000,1,1))))
    def testCountZeroStrRoundTrip(self):
        r = rrule(DAILY, count=0, dtstart=datetime(2000,1,1))
        self.assertEqual(list(rrulestr(str(r))), [])
    def testCountZeroRrulestr(self):
        self.assertEqual(list(rrulestr('FREQ=DAILY;COUNT=0')), [])
    def testCountOne(self):
        self.assertEqual(list(rrule(DAILY, count=1, dtstart=datetime(2000,1,1))),
                         [datetime(2000,1,1)])
EOF
